import{_ as t,o,c as a,a2 as n}from"./chunks/framework.hw3Av5Vn.js";const s="/llamatron/assets/timing_editor.BuLJz5sR.svg",f=JSON.parse('{"title":"Timing","description":"","frontmatter":{},"headers":[],"relativePath":"generators/TIMING.md","filePath":"generators/TIMING.md"}'),r={name:"generators/TIMING.md"};function i(d,e,h,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="timing" tabindex="-1">Timing <a class="header-anchor" href="#timing" aria-label="Permalink to &quot;Timing&quot;">​</a></h1><p>A Timing generator holds four rows of steps, each on (<code>●</code>) or off, as <a href="./../GENERATORS#rows-of-steps">Generators</a> describes, and each changes the notes starting on its lit steps in its own way:</p><ul><li><strong>Rush</strong> plays the note a little early, ahead of the beat, on top of the groove. The first note of a clip can&#39;t move before the clip.</li><li><strong>Drag</strong> plays the note a little late, behind the beat. A step lit in both the Rush and the Drag moves its note by the difference.</li><li><strong>Shorten</strong> plays the note short, its Shorten amount of its length, the rest of its place silent.</li><li><strong>Glide</strong> runs the note into the next one, as the pattern&#39;s Glide row does, so that a synth with glide turned on slides between the two. A note before a rest, or before the same pitch, has nothing to glide into.</li></ul><p>The Glide runs first and then the Shorten, so a note on a step lit in both glides and isn&#39;t shortened; the Rush and the Drag move the notes after every chain has run. A part with no step lit does nothing, and a new Timing generator has none.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+s+'" alt="A clip&#39;s Timing tab"></p><p>Each part is a section, <code>+ Rush</code>, <code>+ Drag</code>, <code>+ Shorten</code> and <code>+ Glide</code>, closed until opened and saying <code>(set)</code> when anything inside holds a value.</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td>Name</td><td><code>ENTER</code> renames it, and every chain using it follows.</td></tr><tr><td>Step</td><td>How long each step of the part&#39;s row lasts: <code>(from pattern)</code>, the clip&#39;s pattern&#39;s step size, or a time from the list every time setting shares.</td></tr><tr><td>Amount</td><td>Rush: 15% of a step by default, up to half a step. Drag: 20% of a step by default, up to half a step. Shorten: 70% of the note&#39;s length by default, from 10% to 95%. Glide: 1/128 by default, from 1/256 to 1/16.</td></tr><tr><td>Steps</td><td>The part&#39;s row, from 1 to 16 steps, shown as <code>[configure]</code>. <code>ENTER</code> opens it: Left and Right move, <code>Space</code> or <code>ENTER</code> turns a step on or off, <code>I</code> and <code>D</code> insert and remove steps.</td></tr><tr><td>Restart</td><td>When every row starts over, as <a href="./../GENERATORS#restart">Generators</a> describes.</td></tr></tbody></table><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Switch on the Timing tab of a clip or a track, or add the Timing generator to a chain, as <code>timing: name</code>, and give clips that chain. <code>examples/learning/12_acid_glide.yml</code> moves an acid line&#39;s slides and short notes with rows of 5, 7 and 3 steps, and its drop loosens the drums with a Rush and Drags.</p>',10)])])}const m=t(r,[["render",i]]);export{f as __pageData,m as default};
